export const BASE_PATH = '/api/v2';

export type OperationId = 'getHealth' | 'startDeviceLogin' | 'pollDeviceLogin' | 'exchangeOidcToken' | 'getMe' | 'createToken' | 'listTokens' | 'revokeToken' | 'createNamespace' | 'pollNamespace' | 'getNamespace' | 'listMembers' | 'setMember' | 'removeMember' | 'searchPackages' | 'getPackage' | 'createPackage' | 'listVersions' | 'getVersion' | 'beginUpload' | 'commitPublish' | 'getPublishStatus' | 'createGroup' | 'getGroup' | 'abortGroup' | 'commitGroup' | 'yankGroup' | 'setYanked' | 'startWebLogin' | 'completeWebLogin' | 'getWebSession' | 'webLogout' | 'createTutorialSandbox';

export type HttpMethod = 'GET' | 'PUT' | 'POST' | 'DELETE' | 'PATCH';

export interface Route {
  readonly operationId: OperationId;
  readonly method: HttpMethod;
  readonly path: string;
  readonly segments: readonly string[];
  readonly pathParams: readonly string[];
  readonly queryParams: readonly string[];
  readonly body: boolean;
  readonly success: readonly number[];
  readonly security: readonly string[];
}

